async function render(){
 if(!data){$('#title').textContent=titles[page];$('#content').innerHTML=loadingError?'<p class=error>Could not load your ledger. Please retry.</p><button id=retry-load>Retry loading</button>':'<p class=muted>Loading your ledger�</p>';if($('#retry-load'))$('#retry-load').onclick=initialize;return;}
 $('#title').textContent=titles[page];$('#filters').hidden=['imports','products'].includes(page);
 document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 if(page==='overview'){overview();$('#content').insertAdjacentHTML('beforeend',offerSummary()+returnSummary());}else if(page==='daily')dailyPage();else if(page==='skus'){skuDashboard();$('#content').insertAdjacentHTML('beforeend',offerSummary()+skuOffers());}else if(page==='orders')ordersPage();else if(page==='returns')returnsPage();else if(page==='payments'){await payments();const section=document.createElement('section');section.className='panel';section.innerHTML='<h2>All settlement entries</h2><p class="muted">All imported order and account entries through the payments-through date, independent of order period and SKU filters.</p>'+txTable(data.settlements);$('#content').append(section);wireOrders();}else if(page==='products')productsPage();else await importsPage();
}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=async()=>{page=b.dataset.page;dailyDrill=null;search='';state='All';returnFilter='All';offerFilter='All';try{await render();}catch(e){notice(e.message,true);}});
$('#apply').onclick=()=>data?refresh().catch(e=>notice(e.message,true)):initialize();$('#close-dialog').onclick=()=>{detailRequest++;$('#detail').close();};
async function initialize(){
 if(initialization)return initialization;
 loadingError='';$('#notice').hidden=true;
 initialization=(async()=>{try{await render();meta=await api('/api/meta');$('#asof').value=meta.today;const initial=await api('/api/report');$('#start').value=initial.first_order||'';$('#end').value=initial.last_order||meta.today;catalog=await api('/api/products');$('#sku').innerHTML='<option value="">All SKUs</option>'+catalog.map(p=>`<option value="${esc(p.sku)}">${esc(p.sku)}</option>`).join('');data=initial;await refresh();}catch(e){loadingError=e.message;notice('Could not load ledger: '+e.message,true);if(!data)await render();}finally{initialization=null;}})();
 return initialization;
}
initialize();
